def is_vowel(c):
    return c.lower() in 'aeiou'

def count_vowels(s):
    return sum(1 for c in s if is_vowel(c))

def is_pal(s):
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]: return False
        l += 1; r -= 1
    return True
